use okkama_runtime_core::{Value,IntValue,heap::{ArrayHeap,ObjectHeap}};
fn main(){ std::thread::Builder::new().stack_size(2*1024*1024).spawn(||{let arrays=ArrayHeap;let heap=ObjectHeap;let mut a=Value::Int(IntValue::from_i64(42));let mut b=a.clone();for _ in 0..20000 {a=arrays.allocate(vec![a.clone(),a]);b=arrays.allocate(vec![b.clone(),b]);}eprintln!("constructed");assert!(heap.equal(&arrays,&a,&b).unwrap());eprintln!("equal finished");assert!(heap.equal(&arrays,&a,&a).unwrap());eprintln!("self equal finished; dropping");drop(a);eprintln!("drop a finished");drop(b);eprintln!("drop b finished");}).unwrap().join().unwrap();}
